for i in range(int(input())):
	(n, q) = input().split()
	n = int(n)
	q = int(q)
	arr = [int(x) for x in input().split()]
	matrix = [[0 for i in range(60)] for j in range(len(arr))]
	for i in range(len(arr)):
		j = 0
		for j in range(60):
			if arr[i] & 1 == 1:
				matrix[i][j] += 1
				if i != 0:
					matrix[i][j] += matrix[i - 1][j]
			else:
				matrix[i][j] += matrix[i - 1][j]
			arr[i] = arr[i] >> 1
	for i in range(q):
		(k, l, r, L, R) = input().split()
		(k, l, r, L, R) = (int(k), int(l) - 1, int(r) - 1, int(L) - 1, int(R) - 1)
		ans1 = 0
		if l != 0:
			ans1 = matrix[r][k] - matrix[l - 1][k]
		else:
			ans1 = matrix[r][k]
		ans2 = r - l + 1 - ans1
		ans3 = matrix[R][k] - matrix[L - 1][k]
		ans4 = R - L + 1 - ans3
		print(ans1 * ans4 + ans2 * ans3)
